import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt();
        long k = nextLong();
        boolean[] owned = new boolean[Math.max(n, 1000000) + 2];
        long answer = 0;
        for (int i = 0; i < m; i++) {
            int v = nextInt();
            if (!owned[v]) {
                owned[v] = true;
                answer++;
            }
        }
        for (int v = 1; v <= n; v++) {
            if (owned[v]) continue;
            if (v > k) break;
            k -= v;
            answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n, m, k := nextInt(), nextInt(), nextInt()
	owned := make([]bool, max(n, 1000000)+2)
	var answer int64
	for i := int64(0); i < m; i++ {
		if v := nextInt(); !owned[v] {
			owned[v] = true
			answer++
		}
	}
	for v := int64(1); v <= n; v++ {
		if owned[v] {
			continue
		}
		if v > k {
			break
		}
		k -= v
		answer++
	}
	w.WriteString(strconv.FormatInt(answer, 10) + "\n")
}
